"use client";

import * as React from "react";
import { cn } from "../lib/utils";
export interface KeyboardCommandSoundsProps { volume?: number; compact?: boolean; className?: string; }
export function KeyboardCommandSounds({ volume = .16, compact = false, className }: KeyboardCommandSoundsProps) {
  const context = React.useRef<AudioContext | null>(null); const [enabled, setEnabled] = React.useState(false); const [last, setLast] = React.useState("Ready");
  const tick = React.useCallback((frequency = 520) => { if (!enabled) return; const audio = context.current ?? (context.current = new AudioContext()); const oscillator = audio.createOscillator(); const gain = audio.createGain(); oscillator.frequency.value = frequency; oscillator.type = "sine"; gain.gain.setValueAtTime(Math.max(.001, volume), audio.currentTime); gain.gain.exponentialRampToValueAtTime(.001, audio.currentTime + .06); oscillator.connect(gain).connect(audio.destination); oscillator.start(); oscillator.stop(audio.currentTime + .07); }, [enabled, volume]);
  React.useEffect(() => { const handler = (event: KeyboardEvent) => { if (event.repeat || !enabled) return; setLast(event.key === "Enter" ? "Command sent" : `${event.key} pressed`); tick(event.key === "Enter" ? 760 : 480); }; window.addEventListener("keydown", handler); return () => window.removeEventListener("keydown", handler); }, [enabled, tick]);
  return <div className={cn("w-full max-w-md rounded-[1.5rem] border border-[#d8e0e6] bg-[#f8fafb] p-4 text-[#16232d] shadow-[0_20px_54px_rgba(23,49,65,.12)] dark:border-white/10 dark:bg-[#10191f] dark:text-white", compact ? "p-3" : "p-5 sm:p-6", className)}><div className="flex items-center justify-between gap-4"><div><p className="text-sm font-semibold">Keyboard sounds</p>{!compact && <p className="mt-1 text-xs text-[#687783] dark:text-white/55">Optional feedback for keys and commands.</p>}</div><button type="button" onClick={() => setEnabled((value) => !value)} aria-pressed={enabled} className={cn("rounded-full px-3 py-1.5 text-xs font-semibold transition focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#2d718c] focus-visible:ring-offset-2 dark:focus-visible:ring-offset-[#10191f]", enabled ? "bg-[#173849] text-white" : "bg-[#e8eef1] text-[#52626d] dark:bg-white/10 dark:text-white/65")}>{enabled ? "On" : "Off"}</button></div><div className="mt-5 flex items-center gap-2 rounded-xl border border-[#dbe3e7] bg-white p-2 dark:border-white/10 dark:bg-white/[.05]"><span className="grid size-8 place-items-center rounded-lg bg-[#eaf1f4] text-xs font-semibold text-[#31586a] dark:bg-white/10 dark:text-white">⌘</span><input aria-label="Try keyboard sounds" onFocus={() => setLast("Listening for keys")} placeholder="Try typing a command…" className="min-w-0 flex-1 bg-transparent px-1 text-sm outline-none placeholder:text-[#97a5ad] dark:placeholder:text-white/35" /><button type="button" aria-label="Play command sound" onClick={() => { setLast("Command sent"); tick(760); }} className="rounded-lg bg-[#173849] px-3 py-2 text-xs font-semibold text-white transition hover:bg-[#24526a] active:scale-95">Run</button></div>{!compact && <p aria-live="polite" className="mt-3 text-xs text-[#687783] dark:text-white/55">{last}</p>}</div>;
}
export default KeyboardCommandSounds;
